import math

n_problems = int(input())
for i in range(1, n_problems + 1):
    n = int(input())
    a = int(input())
    print(f"problem {i}: n = {n}, a = {a}")
    if n == 0:
        print("  derivative: 0")
    else:
        for k in range(1, n + 1):
            print(f"  h^{k - 1}: {math.comb(n, k) * a**(n - k)}")
        print(f"  derivative: {n * a**(n - 1)}")

n_problems = int(input())
for i in range(1, n_problems + 1):
    n = int(input())
    coeffs = []
    for k in range(n + 1):
        coeffs.append(int(input()))
    a = int(input())
    result = []
    for k in range(1, n + 1):
        result.append(k * coeffs[k])
    if len(result) == 0:
        result = [0]
    slope = 0
    for j in range(len(result)):
        slope = slope + result[j] * a**j
    print(f"problem {i}: p' = {result}, p'(a) = {slope}")
